// beacon-chain/blockchain/kzg/kzg.go:RecoverCellsAndKZGProofs
func RecoverCellsAndKZGProofs(cellIndices []uint64, partialCells []Cell) (CellsAndProofs, error) {
    // Go allocation: bounded, max 128 * BytesPerCell = 256KB
    ckzgPartialCells := make([]ckzg4844.Cell, len(partialCells))
    for i := range partialCells { ckzgPartialCells[i] = ckzg4844.Cell(partialCells[i]) }
    // C library order:
    //   1. if (num_cells > CELLS_PER_EXT_BLOB) return C_KZG_BADARGS;  // line 200
    //   2. if (num_cells < CELLS_PER_BLOB) return C_KZG_BADARGS;      // line 206
    //   3. for each index: if >= CELLS_PER_EXT_BLOB return BADARGS;    // lines 211-217
    //   4. new_fr_array(&recovered_cells_fr, FIELD_ELEMENTS_PER_EXT_BLOB)  // line 220 - expensive
    //   5. new_g1_array(&recovered_proofs_g1, CELLS_PER_EXT_BLOB)         // line 223 - expensive
    ckzgCells, ckzgProofs, err := ckzg4844.RecoverCellsAndKZGProofs(cellIndices, ckzgPartialCells)
    if err != nil { return CellsAndProofs{}, errors.Wrap(err, "recover cells and KZG proofs") }
    return makeCellsAndProofs(ckzgCells[:], ckzgProofs[:])
}

